input.newString:
function draw() {
    ctx.clearRect(0, 0, W, H);
    // background gradient
    const grd = ctx.createLinearGradient(0, 0, 0, H);
    grd.addColorStop(0, '#222');
    grd.addColorStop(1, '#000');
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, W, H);
    // scrolling ground line
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, H - 10);
    ctx.lineTo(W, H - 10);
    ctx.stroke();
    // simple parallax stars
    ctx.fillStyle = '#888';
    for (let i = 0; i < 30; i++) {
      const sx = (i * 50 - bgOffset) % W;
      ctx.fillRect(sx, 20 + (i % 5) * 10, 2, 2);
    }
    // player with slight shadow
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x + 2, player.y + 2, player.size, player.size);
    ctx.fillStyle = '#0b0';
    ctx.fillRect(player.x, player.y, player.size, player.size);
    // obstacles with gradient
    obstacles.forEach(o => {
      const grad = ctx.createLinearGradient(o.x, o.y, o.x, o.y + o.h);
      grad.addColorStop(0, '#f44');
      grad.addColorStop(1, '#800');
      ctx.fillStyle = grad;
      ctx.fillRect(o.x, o.y, o.w, o.h);
    });
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + score, 10, 20);
  }

